  GRAMMAR.push({ structure: "真的沒想到……，我們該怎麼自保？", usage: "\"Thật không ngờ…, chúng ta nên tự bảo vệ mình thế nào?\" — bày tỏ bất ngờ rồi hỏi cách ứng phó.", lesson: "GH-08", examples: [ex("真的沒想到公司會一次裁掉這麼多人，我們該怎麼自保？", '', "Thật không ngờ công ty cắt một lúc nhiều người như vậy, chúng ta nên tự bảo vệ thế nào?"), ex("真的沒想到合約裡有這麼多陷阱，我們該怎麼自保？", '', "Thật không ngờ trong hợp đồng có nhiều cái bẫy thế, chúng ta phải tự bảo vệ ra sao?")] });
