  GRAMMAR.push({ structure: "一M接著一M", usage: "\"Hết … này đến … khác\": sau một M lập tức tiếp một M khác, liên tục không ngừng; động từ đặt phía sau.", lesson: "P4-06", examples: [ex("我就一杯接著一杯，不停地喝。", '', "Tôi cứ uống hết cốc này đến cốc khác không ngừng."), ex("他好喜歡表現，叫他唱歌，他就一首接著一首地唱了半夜。", '', "Anh ta rất thích thể hiện, bảo hát là hát hết bài này đến bài khác suốt nửa đêm.")] });
  GRAMMAR.push({ structure: "VV看", usage: "\"V thử xem\": 看 sau động từ lặp lại biểu thị thử làm; động từ thường đơn âm tiết, có thể kèm tân ngữ.", lesson: "P4-06", examples: [ex("他們也叫我抽抽看，我好想試試。", '', "Họ cũng bảo tôi hút thử xem, tôi rất muốn thử."), ex("這個方法不錯，你用用看就知道了。", '', "Cách này hay đấy, bạn dùng thử là biết.")] });
  GRAMMAR.push({ structure: "受(到)N的影響", usage: "\"Chịu ảnh hưởng của N\": N tác động lên chủ ngữ đứng trước 受(到); mang sắc thái bị động.", lesson: "P4-06", examples: [ex("我想有的人可能是受了壞朋友的影響。", '', "Tôi nghĩ có người có thể bị bạn xấu ảnh hưởng."), ex("小李受了他父親的影響，才在大學學戲劇的。", '', "Tiểu Lý chịu ảnh hưởng của bố nên mới học sân khấu ở đại học.")] });
  GRAMMAR.push({ structure: "在……(之)下", usage: "\"Trong/dưới (điều kiện) …\": cụm danh từ sau 在 là điều kiện cho mệnh đề phía sau.", lesson: "P4-06", examples: [ex("在這種情形下，想戒就難了。", '', "Trong tình hình đó, muốn cai thì khó rồi."), ex("在考試的壓力下，李愛美每天下了課就去補習。", '', "Dưới áp lực thi cử, ngày nào tan học Lý Ái Mỹ cũng đi học thêm.")] });
  GRAMMAR.push({ structure: "按照NP的規定……", usage: "\"Theo quy định của NP …\": sau 規定 là quy định hoặc yêu cầu bắt buộc do NP đặt ra.", lesson: "P4-06", examples: [ex("按照你們法律的規定，不是二十一歲以上才可以喝酒嗎？", '', "Theo quy định pháp luật của các bạn, chẳng phải từ 21 tuổi trở lên mới được uống rượu sao?"), ex("按照圖書館的規定，不能帶飲料進去。", '', "Theo quy định của thư viện, không được mang đồ uống vào.")] });
  GRAMMAR.push({ structure: "N/NU-M以上（以下、以內、以外）", usage: "\"… trở lên / trở xuống / trong vòng / ngoài\": tính cả mốc được nêu; 以上 đứng một mình nghĩa là \"những điều nói trên\".", lesson: "P4-06", examples: [ex("十八歲以上才可以看限制級的片子。", '', "Từ 18 tuổi trở lên mới được xem phim loại cấm."), ex("今天氣溫已經低到零度以下，所以下雪了。", '', "Hôm nay nhiệt độ đã xuống dưới 0 độ nên có tuyết.")] });
  GRAMMAR.push({ structure: "為了……而……", usage: "\"Vì (mục đích) … mà …\": sau 為了 là mục đích; 而 là liên từ nghĩa như 所以/就; dùng trong văn viết hoặc lời trang trọng.", lesson: "P4-06", examples: [ex("怎麼會有人為了不想睡覺而吸毒呢？", '', "Sao lại có người vì không muốn ngủ mà dùng ma tuý?"), ex("我並不是為了健康而戒菸，是為了女朋友才戒的。", '', "Tôi không phải vì sức khoẻ mà cai thuốc, là vì bạn gái mới cai.")] });
  CONVERSATIONS.push({"title":"PAVC4 · L6 小心壞習慣","lines":[{"speaker":"","zh":"（宿舍裡）","pinyin":"","en":"(Trong ký túc xá)"},{"speaker":"偉立","zh":"欸，幫個忙，把你的臭襪子拿走，好不好？","pinyin":"","en":"Này, giúp cái, mang đôi tất thối của cậu đi được không?"},{"speaker":"建國","zh":"對不起，我起不來。麻煩你先倒杯水給我。我喉嚨好乾，頭也痛得受不了。","pinyin":"","en":"Xin lỗi, tớ không dậy nổi. Phiền cậu rót giúp tớ cốc nước trước. Họng tớ khô quá, đầu cũng đau không chịu nổi."},{"speaker":"偉立","zh":"好吧，誰叫我跟你住一個房間呢！？你昨天晚上到底喝了多少酒？怎麼醉成這樣？","pinyin":"","en":"Thôi được, ai bảo tớ ở chung phòng với cậu chứ!? Tối qua rốt cuộc cậu uống bao nhiêu rượu? Sao say đến mức này?"},{"speaker":"建國","zh":"我不知道。我只記得他們有一大桶啤酒，我就一杯接著一杯，不停地喝，喝著喝著頭就開始暈了。我想回來，可是一出門就吐了，差一點吐在欣欣的裙子上。後來也不知道是怎麼走回來的。","pinyin":"","en":"Tớ không biết. Tớ chỉ nhớ họ có một thùng bia to, tớ cứ uống hết cốc này đến cốc khác không ngừng, uống mãi đầu bắt đầu choáng. Tớ muốn về, nhưng vừa ra khỏi cửa đã nôn, suýt nữa nôn lên váy Hân Hân. Sau đó cũng không biết đi về bằng cách nào."},{"speaker":"偉立","zh":"誰開的派對？","pinyin":"","en":"Ai tổ chức bữa tiệc vậy?"},{"speaker":"建國","zh":"我也不清楚是誰開的，反正欣欣要去，我就跟著去了。現在頭這麼痛，真後悔喝了那麼多酒。","pinyin":"","en":"Tớ cũng không rõ ai tổ chức, dù sao Hân Hân đi nên tớ đi theo. Giờ đầu đau thế này, thật hối hận vì uống nhiều thế."},{"speaker":"偉立","zh":"你活該。下次不敢了吧？","pinyin":"","en":"Đáng đời cậu. Lần sau không dám nữa chứ?"},{"speaker":"建國","zh":"不敢了。欸，昨天晚上有人抽大麻菸，他們也叫我抽抽看，我好想試試，不過最後還是沒敢抽。","pinyin":"","en":"Không dám nữa. À, tối qua có người hút cần sa, họ cũng bảo tớ hút thử, tớ rất muốn thử, nhưng cuối cùng vẫn không dám."},{"speaker":"偉立","zh":"嗯，大麻，還是少碰比較好，長時間吸食，對身體的傷害很大。還有古柯鹼更不能碰，這種東西很危險，萬一上了癮就麻煩了。","pinyin":"","en":"Ừ, cần sa thì tốt nhất đừng đụng vào, hút lâu dài rất hại sức khoẻ. Còn cocaine càng không được đụng, thứ này rất nguy hiểm, lỡ nghiện thì phiền to."},{"speaker":"建國","zh":"我媽、我老師也都這麼說，既然大家都知道，為什麼還有這麼多人吸毒呢？","pinyin":"","en":"Mẹ tớ, thầy tớ cũng đều nói vậy, đã ai cũng biết thì sao vẫn có nhiều người hút chích ma tuý thế?"},{"speaker":"偉立","zh":"我想有的人可能是受了壞朋友的影響，開始的時候，也許只是好奇，後來發現可以逃避現實，減輕壓力，慢慢地就上了癮，而且越吸越多，在這種情形下，想戒就難了。","pinyin":"","en":"Tớ nghĩ có người có thể bị bạn xấu ảnh hưởng, lúc đầu có lẽ chỉ tò mò, sau phát hiện có thể trốn tránh thực tại, giảm áp lực, dần dần nghiện, càng hút càng nhiều, trong tình hình đó muốn cai thì khó rồi."},{"speaker":"建國","zh":"減輕壓力難道沒有別的辦法嗎？","pinyin":"","en":"Giảm áp lực lẽ nào không có cách khác sao?"},{"speaker":"偉立","zh":"要是能找個人說說心裡的話，感覺就會好一點。","pinyin":"","en":"Nếu tìm được ai đó để nói ra những điều trong lòng thì sẽ thấy dễ chịu hơn."},{"speaker":"建國","zh":"這麼說，我應該感謝常有人願意聽我抱怨嘍？","pinyin":"","en":"Nói vậy là tớ nên cảm ơn vì thường có người chịu nghe tớ than phiền à?"},{"speaker":"偉立","zh":"你總算明白了。起來刷牙、洗臉吧！洗個澡會舒服一點兒。","pinyin":"","en":"Cuối cùng cậu cũng hiểu rồi. Dậy đánh răng rửa mặt đi! Tắm một cái sẽ dễ chịu hơn."},{"speaker":"","zh":"（在餐廳）","pinyin":"","en":"(Ở nhà ăn)"},{"speaker":"偉立","zh":"嗨！李平，好久沒見了。","pinyin":"","en":"Chào Lý Bình, lâu rồi không gặp."},{"speaker":"李平","zh":"是啊！這裡坐吧！最近好嗎？","pinyin":"","en":"Ừ! Ngồi đây đi! Dạo này khoẻ không?"},{"speaker":"偉立","zh":"我還不錯，建國可不好。","pinyin":"","en":"Tớ thì ổn, Kiến Quốc thì không ổn."},{"speaker":"李平","zh":"他怎麼了？怎麼沒來吃午飯？","pinyin":"","en":"Cậu ấy làm sao? Sao không đến ăn trưa?"},{"speaker":"偉立","zh":"昨天晚上喝了太多酒，到現在還在頭痛呢！","pinyin":"","en":"Tối qua uống quá nhiều rượu, đến giờ vẫn còn đau đầu!"},{"speaker":"李平","zh":"他喝酒了？按照你們法律的規定，不是二十一歲以上才可以喝酒嗎？","pinyin":"","en":"Cậu ấy uống rượu à? Theo quy định pháp luật bên các cậu, chẳng phải từ 21 tuổi trở lên mới được uống rượu sao?"},{"speaker":"偉立","zh":"規定是規定，可是總有人不遵守啊！而且很多人以為啤酒不是酒，喝一點沒關係。","pinyin":"","en":"Quy định là quy định, nhưng lúc nào cũng có người không tuân thủ! Hơn nữa nhiều người nghĩ bia không phải rượu, uống chút không sao."},{"speaker":"李平","zh":"可是他為什麼喝那麼多呢？是不是有什麼問題？","pinyin":"","en":"Nhưng sao cậu ấy uống nhiều thế? Có phải có vấn đề gì không?"},{"speaker":"偉立","zh":"那倒不是。他大概因為剛交了女朋友，一高興，就喝多了。他只是喝醉了，聽說別人還抽大麻呢！","pinyin":"","en":"Không phải đâu. Chắc vì cậu ấy mới có bạn gái, vui quá nên uống nhiều. Cậu ấy chỉ say thôi, nghe nói người khác còn hút cần sa cơ!"},{"speaker":"李平","zh":"真的？！沒想到建國會參加這樣的派對。這裡的大學生吸毒的情形嚴重嗎？","pinyin":"","en":"Thật à?! Không ngờ Kiến Quốc lại dự bữa tiệc như vậy. Tình trạng sinh viên ở đây dùng ma tuý có nghiêm trọng không?"},{"speaker":"偉立","zh":"我想這得看地區，有些高中的情形比大學嚴重。台灣呢？","pinyin":"","en":"Tớ nghĩ còn tuỳ khu vực, có những trường trung học còn nghiêm trọng hơn đại học. Còn Đài Loan thì sao?"},{"speaker":"李平","zh":"這些年，吸毒的青少年越來越多了。聽說在夜店裡就可以買到搖頭丸，還有一種毒品叫安非他命，吸食以後精神很好，可以不睡覺。","pinyin":"","en":"Mấy năm nay thanh thiếu niên dùng ma tuý ngày càng nhiều. Nghe nói ở hộp đêm có thể mua được thuốc lắc, còn một loại ma tuý gọi là amphetamine, dùng xong rất tỉnh táo, có thể không ngủ."},{"speaker":"偉立","zh":"我以為吸毒的人是為了逃避現實，暫時快樂一下。怎麼會有人為了不想睡覺而吸毒呢？","pinyin":"","en":"Tớ cứ tưởng người dùng ma tuý là để trốn tránh thực tại, vui tạm một lúc. Sao lại có người dùng ma tuý chỉ vì không muốn ngủ?"},{"speaker":"李平","zh":"要是能不睡覺，不是可以多做些事，多賺些錢嗎？其實最可怕的還是黑社會的人，不但販毒，還用毒品控制青少年，逼他們去犯罪。","pinyin":"","en":"Nếu không phải ngủ, chẳng phải làm được nhiều việc hơn, kiếm được nhiều tiền hơn sao? Thật ra đáng sợ nhất vẫn là bọn xã hội đen, không chỉ buôn ma tuý mà còn dùng ma tuý khống chế thanh thiếu niên, ép chúng đi phạm tội."},{"speaker":"偉立","zh":"唉！大家都應該重視這個世界性的大問題。政府必須趕快想辦法把那些販毒的人抓起來，免得他們害更多的人。","pinyin":"","en":"Haizz! Mọi người đều nên coi trọng vấn đề lớn mang tính toàn cầu này. Chính phủ phải nhanh chóng tìm cách bắt bọn buôn ma tuý, kẻo chúng hại thêm nhiều người."},{"speaker":"李平","zh":"是啊！這個問題，家庭、學校、社會也有責任，應該一起來解決。","pinyin":"","en":"Đúng vậy! Vấn đề này gia đình, nhà trường, xã hội cũng có trách nhiệm, nên cùng nhau giải quyết."}],"questions":[{"prompt":"建國為什麼頭痛？","options":["昨天晚上喝了太多酒","他感冒了","他抽了大麻","他一夜沒睡覺"],"correct":0},{"prompt":"建國為什麼去參加那個派對？","options":["欣欣要去，他就跟著去了","他是主人","他想喝啤酒","偉立叫他去的"],"correct":0},{"prompt":"昨天晚上有人叫建國做什麼？他做了沒有？","options":["抽大麻，他最後沒敢抽","喝啤酒，他沒喝","跳舞，他跳了","唱歌，他沒唱"],"correct":0},{"prompt":"偉立認為有些人為什麼會吸毒？","options":["受了壞朋友的影響，想逃避現實、減輕壓力","因為毒品很便宜","因為法律允許","因為想參加派對"],"correct":0},{"prompt":"按照美國法律的規定，幾歲以上才可以喝酒？","options":["二十一歲","十八歲","十六歲","二十歲"],"correct":0},{"prompt":"建國為什麼喝那麼多？","options":["剛交了女朋友，一高興就喝多了","他心情不好","他壓力很大","他跟人比賽"],"correct":0},{"prompt":"李平說有人吸安非他命是為了什麼？","options":["可以不睡覺，多做些事、多賺些錢","為了減肥","為了逃避考試","為了睡得好"],"correct":0}]});
  // ---- PAVC4 · L7 感情的事
